using System.Security.Cryptography;
using System.Text;
using EquipmentRental.Models;
using EquipmentRental.Services;
using Microsoft.AspNetCore.Mvc;
namespace EquipmentRental.Controllers;
public class HomeController(StoreService store) : Controller {
 public IActionResult Index(string? q, int? category) { var items=store.Data.Equipment.Where(x=>x.State!=EquipmentState.WrittenOff); if(!string.IsNullOrWhiteSpace(q)) items=items.Where(x=>(x.Name+" "+x.Description+" "+x.Tags).Contains(q,StringComparison.OrdinalIgnoreCase)); if(category>0) items=items.Where(x=>x.CategoryId==category); ViewBag.Categories=store.Data.Categories; ViewBag.Query=q; ViewBag.Category=category; return View(items.ToList()); }
 public IActionResult Login() => View();
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Login(string email,string password) { var u=store.Data.Users.FirstOrDefault(x=>x.Email.Equals(email??"",StringComparison.OrdinalIgnoreCase)); if(u==null || !Verify(password??"",u.Password)) { ModelState.AddModelError("", "Неверная почта или пароль"); return View(); } HttpContext.Session.SetInt32("UserId",u.Id); return RedirectToAction("Index"); }
 public IActionResult Register() => View();
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Register(string name,string email,string password) { name=(name??"").Trim(); email=(email??"").Trim().ToLowerInvariant(); if(name.Length<2 || !email.Contains('@') || (password??"").Length<8 || store.Data.Users.Any(x=>x.Email.Equals(email,StringComparison.OrdinalIgnoreCase))) { ModelState.AddModelError("", "Введите имя, уникальную почту и пароль не короче 8 символов."); return View(); } var u=new User { Id=store.NextId(store.Data.Users), Name=name, Email=email, Password=Hash(password!), Role=UserRole.Client }; store.Data.Users.Add(u); store.Persist(); HttpContext.Session.SetInt32("UserId",u.Id); return RedirectToAction("Index"); }
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Logout() { HttpContext.Session.Clear(); return RedirectToAction("Index"); }
 public static string Hash(string password) { var salt=RandomNumberGenerator.GetBytes(16); var hash=Rfc2898DeriveBytes.Pbkdf2(password,salt,100000,HashAlgorithmName.SHA256,32); return Convert.ToBase64String(salt)+":"+Convert.ToBase64String(hash); }
 public static bool Verify(string password,string stored) { if(!stored.Contains(':')) return password==stored; try { var p=stored.Split(':'); var expected=Convert.FromBase64String(p[1]); var actual=Rfc2898DeriveBytes.Pbkdf2(password,Convert.FromBase64String(p[0]),100000,HashAlgorithmName.SHA256,32); return CryptographicOperations.FixedTimeEquals(actual,expected); } catch { return false; } }
}
public class BookingsController(StoreService store) : Controller {
 private User? Current => store.Data.Users.FirstOrDefault(u=>u.Id==HttpContext.Session.GetInt32("UserId"));
 public IActionResult Index() { if(Current==null) return RedirectToAction("Login","Home"); ViewBag.Items=store.Data.Equipment; return View(store.Data.Bookings.Where(b=>b.UserId==Current.Id).OrderByDescending(b=>b.CreatedAt).ToList()); }
 public IActionResult Create(int id) { if(Current==null) return RedirectToAction("Login","Home"); var item=store.Data.Equipment.FirstOrDefault(x=>x.Id==id); if(item==null) return NotFound(); return View(item); }
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Create(int id,DateTime startDate,DateTime endDate) { if(Current==null) return RedirectToAction("Login","Home"); var item=store.Data.Equipment.FirstOrDefault(x=>x.Id==id); if(item==null) return NotFound(); lock(store) { if(startDate.Date<DateTime.Today || endDate.Date<startDate.Date || (endDate-startDate).TotalDays>365 || item.State!=EquipmentState.Available || !store.IsAvailable(id,startDate,endDate)) { ModelState.AddModelError("", "Проверьте даты: оборудование недоступно на выбранный период или указан неверный срок."); return View(item); } store.Data.Bookings.Add(new Booking { Id=store.NextId(store.Data.Bookings), EquipmentId=id, UserId=Current.Id, StartDate=startDate.Date, EndDate=endDate.Date, TotalPrice=store.Price(id,startDate,endDate), DailyRate=item.PricePerDay }); store.Persist(); } TempData["Message"]="Бронирование создано! Менеджер свяжется с вами для подтверждения."; return RedirectToAction("Index"); }
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Cancel(int id) { if(Current==null) return RedirectToAction("Login","Home"); var b=store.Data.Bookings.FirstOrDefault(x=>x.Id==id && x.UserId==Current.Id); if(b?.Status is BookingStatus.Booked or BookingStatus.Confirmed) { b.Status=BookingStatus.Cancelled; store.Persist(); } return RedirectToAction("Index"); }
}
public class ManagerController(StoreService store) : Controller {
 private bool Allowed => store.Data.Users.Any(u=>u.Id==HttpContext.Session.GetInt32("UserId") && u.Role is UserRole.Manager or UserRole.Admin);
 public IActionResult Index() { if(!Allowed) return StatusCode(403); ViewBag.Users=store.Data.Users; ViewBag.Items=store.Data.Equipment; ViewBag.Store=store; foreach(var booking in store.Data.Bookings.Where(b=>b.Status==BookingStatus.Issued && b.EndDate.Date<DateTime.Today)) booking.Status=BookingStatus.Overdue; store.Persist(); return View(store.Data.Bookings.OrderByDescending(x=>x.CreatedAt).ToList()); }
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Update(int id,string action,string? condition,decimal damageFine=0,int unitId=0) { if(!Allowed) return StatusCode(403); var b=store.Data.Bookings.FirstOrDefault(x=>x.Id==id); if(b==null) return NotFound(); if(action=="confirm" && b.Status==BookingStatus.Booked) b.Status=BookingStatus.Confirmed; if(action=="issue" && b.Status==BookingStatus.Confirmed) { lock(store) { if(!store.AssignUnit(b.Id,b.EquipmentId,unitId)) { TempData["Message"]="Выберите свободный исправный экземпляр."; return RedirectToAction("Index"); } b.Status=BookingStatus.Issued; store.Persist(); } return RedirectToAction("Index"); } if(action=="return" && (b.Status is BookingStatus.Issued or BookingStatus.Overdue)) { b.Status=BookingStatus.Returned; b.ReturnCondition=condition; var item=store.Data.Equipment.First(x=>x.Id==b.EquipmentId); b.Fine=Math.Max(0,(DateTime.Today-b.EndDate.Date).Days)*(b.DailyRate>0?b.DailyRate:item.PricePerDay)+Math.Max(0,damageFine); } store.Persist(); return RedirectToAction("Index"); }
}
public class AdminController(StoreService store) : Controller {
 private bool Allowed => store.Data.Users.Any(u=>u.Id==HttpContext.Session.GetInt32("UserId") && u.Role==UserRole.Admin);
 public IActionResult Index() { if(!Allowed) return StatusCode(403); ViewBag.Categories=store.Data.Categories; ViewBag.Users=store.Data.Users; ViewBag.Units=store.InventoryRows(); ViewBag.UnitHistory=store.InventoryHistory(); return View(store.Data.Equipment); }
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Save(int id,string name,string description,int categoryId,decimal pricePerDay,int totalUnits,EquipmentState state,string imageUrl) { if(!Allowed) return StatusCode(403); if(string.IsNullOrWhiteSpace(name)||pricePerDay<=0||totalUnits<1||!store.Data.Categories.Any(c=>c.Id==categoryId)) { TempData["Message"]="Проверьте данные оборудования."; return RedirectToAction("Index"); } var item=store.Data.Equipment.FirstOrDefault(x=>x.Id==id); if(item==null) { item=new Equipment { Id=store.NextId(store.Data.Equipment) }; store.Data.Equipment.Add(item); } item.Name=name.Trim(); item.Description=description??""; item.CategoryId=categoryId; item.PricePerDay=pricePerDay; if(id==0){item.TotalUnits=totalUnits; item.AvailableUnits=totalUnits;} item.State=state; item.ImageUrl=imageUrl??""; store.Persist(); return RedirectToAction("Index"); }
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Inventory(int id,int totalUnits,int repairUnits,int writtenOffUnits) { if(!Allowed) return StatusCode(403); var item=store.Data.Equipment.FirstOrDefault(x=>x.Id==id); if(item==null) return NotFound(); if(totalUnits<item.TotalUnits || repairUnits<0 || writtenOffUnits<0 || repairUnits+writtenOffUnits>totalUnits) { TempData["Message"]="Некорректное количество единиц."; return RedirectToAction("Index"); } lock(store) { if(store.HasIssuedUnits(id) && (repairUnits!=item.RepairUnits || writtenOffUnits!=item.WrittenOffUnits)) { TempData["Message"]="Сначала примите выданные экземпляры, затем измените состояние склада."; return RedirectToAction("Index"); } int capacity=totalUnits-repairUnits-writtenOffUnits; var bs=store.Data.Bookings.Where(b=>b.EquipmentId==id && (b.Status is BookingStatus.Booked or BookingStatus.Confirmed or BookingStatus.Issued or BookingStatus.Overdue)).ToList(); if(bs.Any(b=>bs.Count(x=>x.StartDate.Date<=b.StartDate.Date && x.EndDate.Date>=b.StartDate.Date)>capacity)) { TempData["Message"]="Количество исправных единиц меньше числа активных броней."; return RedirectToAction("Index"); } item.TotalUnits=totalUnits;item.RepairUnits=repairUnits;item.WrittenOffUnits=writtenOffUnits;item.AvailableUnits=capacity; store.Persist(); } return RedirectToAction("Index"); }
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Category(int id,string name) { if(!Allowed) return StatusCode(403); if(string.IsNullOrWhiteSpace(name)) return RedirectToAction("Index"); var c=store.Data.Categories.FirstOrDefault(x=>x.Id==id); if(c==null){c=new Category { Id=store.NextId(store.Data.Categories) };store.Data.Categories.Add(c);} c.Name=name.Trim();store.Persist();return RedirectToAction("Index"); }
 [HttpPost, ValidateAntiForgeryToken] public IActionResult Role(int id,UserRole role) { if(!Allowed) return StatusCode(403); var user=store.Data.Users.FirstOrDefault(x=>x.Id==id); if(user!=null && user.Id!=HttpContext.Session.GetInt32("UserId")) { user.Role=role; store.Persist(); } return RedirectToAction("Index"); }
}
public class StatsController(StoreService store) : Controller { public IActionResult Index() { if(!store.Data.Users.Any(u=>u.Id==HttpContext.Session.GetInt32("UserId") && u.Role==UserRole.Admin)) return StatusCode(403); ViewBag.Items=store.Data.Equipment; return View(store.Data.Bookings); } }






